class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1 or numRows >= len(s):
            return s
        grid = [[""] * len(s) for _ in range(numRows)]
        row = col = 0
        going_down = True
        for ch in s:
            grid[row][col] = ch
            if going_down:
                if row == numRows - 1:
                    going_down = False
                    row -= 1
                    col += 1
                else:
                    row += 1
            else:
                if row == 0:
                    going_down = True
                    row += 1
                else:
                    row -= 1
                    col += 1
        out = []
        for r in range(numRows):
            for c in range(len(s)):
                if grid[r][c]:
                    out.append(grid[r][c])
        return "".join(out)

