class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1 or numRows >= len(s):
            return s
        cycle = 2 * numRows - 2
        ans = []
        for row in range(numRows):
            i = row
            while i < len(s):
                ans.append(s[i])
                diag = i + cycle - 2 * row
                if 0 < row < numRows - 1 and diag < len(s):
                    ans.append(s[diag])
                i += cycle
        return "".join(ans)

